package cn.zhuatech.marketingai.service; import jakarta.validation.constraints.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class CampaignBriefService { public record Request(@NotBlank String product,@NotBlank String audience,@NotBlank String channel,@NotBlank String tone,boolean containsPerformanceClaim){} public record Result(String headline,List<String> contentAngles,List<String> reviewChecklist,String channelGuidance){} public Result build(Request r){var angles=List.of(r.audience()+"的核心业务问题",r.product()+"的可验证价值","真实场景与下一步行动");var checks=new ArrayList<String>(List.of("人工核验产品事实","检查品牌术语与敏感表达","确认素材版权与人物授权"));if(r.containsPerformanceClaim())checks.add("效果数据必须提供可追溯证据");return new Result("为"+r.audience()+"准备的"+r.product()+"实践指南",angles,checks,r.channel()+"渠道采用"+r.tone()+"表达，发布前由品牌负责人审核");} }
